import re,json,os
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def transform(g):
    H,W=len(g),len(g[0])
    out=[r[:] for r in g]
    # find connected regions of cells != 8
    seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=8 and not seen[i][j]:
                stack=[(i,j)]; cells=[]; seen[i][j]=True
                while stack:
                    r,c=stack.pop(); cells.append((r,c))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<H and 0<=nc<W and g[nr][nc]!=8 and not seen[nr][nc]:
                            seen[nr][nc]=True; stack.append((nr,nc))
                r0=min(r for r,c in cells); r1=max(r for r,c in cells)
                c0=min(c for r,c in cells); c1=max(c for r,c in cells)
                nz=[(r-r0,c-c0,g[r][c]) for r,c in cells if g[r][c]!=0]
                ph=max(r for r,c,v in nz)+1; pw=max(c for r,c,v in nz)+1
                pat=[[0]*pw for _ in range(ph)]
                for r,c,v in nz: pat[r][c]=v
                for r in range(r0,r1+1):
                    for c in range(c0,c1+1):
                        out[r][c]=pat[(r-r0)%ph][(c-c0)%pw]
    return out

print(transform(G['Demo pair 1 input'])==G['Demo pair 1 output'])
res=transform(G['Test input'])
print(json.dumps(res))

